const tokens = $('02a_busca_tokens').all().map(i => i.json);
const tokenRD = tokens.find(t => t.service === 'rdstation') || null;
const agora = new Date();
const rdExpiraEm = (tokenRD && tokenRD.expires_at) ? new Date(tokenRD.expires_at) : null;
const rdHorasParaExpirar = (rdExpiraEm && !isNaN(rdExpiraEm)) ? (rdExpiraEm - agora) / (1000 * 60 * 60) : null;

// O token RD Station e renovado a cada 1h-1h30 pelo workflow Renovar Token (Anexo C.3) --
// por isso o alerta so faz sentido quando o token JA expirou (falha real da renovacao
// automatica), nao por estar perto de expirar (ele sempre esta perto, por design).
let ok = true;
let detalhe = 'Token RD Station valido.';
if (!tokenRD || rdHorasParaExpirar === null) {
  ok = false;
  detalhe = 'Token RD Station nao encontrado ou sem expires_at na aba tokens.';
} else if (rdHorasParaExpirar < 0) {
  ok = false;
  detalhe = `Token RD Station expirado ha ${Math.abs(rdHorasParaExpirar).toFixed(1)}h -- possivel falha na renovacao automatica (workflow Renovar Token).`;
} else {
  detalhe = `Token RD Station valido, expira em ${rdHorasParaExpirar.toFixed(1)}h (renovacao automatica de hora em hora).`;
}

return [{ json: { token_ok: ok, token_detalhe: detalhe } }];

const leads = $('03a_busca_base_funil').all().map(i => i.json);
const totalLeads = leads.length;
const cabecalhoIntegro = totalLeads > 0 && Object.prototype.hasOwnProperty.call(leads[0], 'lead_id');

let ok = true;
let detalhe = `Base integra: ${totalLeads} lead(s), cabecalho com lead_id.`;
if (totalLeads === 0) {
  ok = false;
  detalhe = 'base_funil_completo esta vazia (0 linhas).';
} else if (!cabecalhoIntegro) {
  ok = false;
  detalhe = 'Cabecalho da base_funil_completo nao contem a coluna lead_id -- possivel aba trocada (bug de gid).';
}

return [{ json: { base_ok: ok, base_detalhe: detalhe, base_total_leads: totalLeads } }];

const resp = $('04a_busca_execucao_regua').item.json;
const execucoes = Array.isArray(resp.data) ? resp.data : [];
const ultima = execucoes.length > 0 ? execucoes[0] : null;
const agora = new Date();
const janelaHoras = 25;

let ok = true;
let detalhe = '';
if (!ultima) {
  ok = false;
  detalhe = '04_Regua_Followup nao tem nenhuma execucao registrada.';
} else {
  const iniciadaEm = new Date(ultima.startedAt);
  const horasDesde = (agora - iniciadaEm) / (1000 * 60 * 60);
  if (isNaN(horasDesde)) {
    ok = false;
    detalhe = 'Nao foi possivel calcular ha quanto tempo foi a ultima execucao do 04_Regua_Followup.';
  } else if (horasDesde > janelaHoras) {
    ok = false;
    detalhe = `04_Regua_Followup nao executa ha ${horasDesde.toFixed(1)}h (esperado: diariamente, janela de ${janelaHoras}h) -- possivel Schedule Trigger parado.`;
  } else {
    detalhe = `Ultima execucao do 04_Regua_Followup ha ${horasDesde.toFixed(1)}h.`;
  }
}

return [{ json: { regua_ok: ok, regua_detalhe: detalhe } }];

const m = $('merge_checks').item.json;
const checks = [
  { nome: '02_check_token_rdstation', ok: m.token_ok, detalhe: m.token_detalhe },
  { nome: '03_check_base_funil', ok: m.base_ok, detalhe: m.base_detalhe },
  { nome: '04_check_execucoes_regua', ok: m.regua_ok, detalhe: m.regua_detalhe },
];

const falhas = checks.filter(c => !c.ok);
const tem_problema = falhas.length > 0;

return [{
  json: {
    tem_problema,
    no_origem: falhas.map(f => f.nome).join(', '),
    mensagem_erro: falhas.map(f => f.detalhe).join(' | '),
    timestamp: $now.toISO(),
    resumo: checks,
  }
}];
